    /// The updated authentication configuration details for the data accessor. This specifies how the ISV will authenticate when accessing data through this data accessor. authenticationType -&gt; (string) [required] The type of authentication to use for the data accessor. This determines how the ISV authenticates when accessing data. You can use one of two authentication types: • AWS_IAM_IDC_TTI - Authentication using IAM Identity Center Trusted Token Issuer (TTI). This authentication type allows the ISV to use a trusted token issuer to generate tokens for accessing the data. • AWS_IAM_IDC_AUTH_CODE - Authentication using IAM Identity Center authorization code flow. This authentication type uses the standard OAuth 2.0 authorization code flow for authentication. Possible values: • AWS_IAM_IDC_TTI • AWS_IAM_IDC_AUTH_CODE authenticationConfiguration -&gt; (tagged union structure) The specific authentication configuration based on the authentication type. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: idcTrustedTokenIssuerConfiguration. idcTrustedTokenIssuerConfiguration -&gt; (structure) Configuration for IAM Identity Center Trusted Token Issuer (TTI) authentication used when the authentication type is AWS_IAM_IDC_TTI . idcTrustedTokenIssuerArn -&gt; (string) [required] The Amazon Resource Name (ARN) of the IAM Identity Center Trusted Token Issuer that will be used for authentication. Constraints: • min: 0 • max: 1284 • pattern: arn:[a-z0-9-\.]{1,63}:sso::[0-9]{12}:trustedTokenIssuer/(sso)?ins-[a-zA-Z0-9-.]{16}/tti-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12} externalIds -&gt; (list) A list of external identifiers associated with this authentication configuration. These are used to correlate the data accessor with external systems. Constraints: • min: 1 • max: 1 (string) Constraints: • min: 1 • max: 1000 • pattern: [a-zA-Z0-9][a-zA-Z0-9_-]* Shorthand Syntax: authenticationType=string,authenticationConfiguration={idcTrustedTokenIssuerConfiguration={idcTrustedTokenIssuerArn=string}},externalIds=string,string JSON Syntax: { "authenticationType": "AWS_IAM_IDC_TTI"|"AWS_IAM_IDC_AUTH_CODE", "authenticationConfiguration": { "idcTrustedTokenIssuerConfiguration": { "idcTrustedTokenIssuerArn": "string" } }, "externalIds": ["string", ...] }
    /// </summary>
    [CliOption("--authentication-detail")]
    public string? AuthenticationDetail { get; set; }

    /// <summary>
    /// The updated friendly name for the data accessor. Constraints: • min: 1 • max: 100 • pattern: [a-zA-Z0-9][a-zA-Z0-9_-]*
    /// </summary>
    [CliOption("--display-name")]
    public string? DisplayName { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

        yield break;
    }

